with department_stats as (select dept_id, sum(case when job_title = 'Intern' then 1 else 0 end) as intern_count, round((100 * sum(case when job_title = 'Analyst' then 1 else 0 end)) / count(*), 1) as pct_analyst from employees where length(email) > 14 group by dept_id) select d.id, d.location, d.budget, ds.intern_count, ds.pct_analyst from departments d left join department_stats ds on d.id = ds.dept_id order by d.location
